function icon(name: keyof typeof vectors) {
  const vector = vectors[name];
  const component = forwardRef<Svg, LucideProps>(
    ({ size = 24, color = '#FFFFFF', ...props }, ref) => (
      <Svg
        {...props}
        ref={ref}
        width={size}
        height={size}
        viewBox={'0 0 ' + vector.viewport.join(' ')}
        accessible={false}
      >
        {vector.paths.map((path, index) => (
          <Path
            key={index}
            d={path.d}
            fill={path.filled ? color : 'none'}
            stroke={path.stroked ? color : 'none'}
            strokeWidth={path.strokeWidth}
            strokeLinecap={path.strokeLinecap}
            strokeLinejoin={path.strokeLinejoin}
            strokeOpacity={path.strokeOpacity}
            fillOpacity={path.opacity}
            fillRule={path.fillRule}
            transform={path.transform || undefined}
          />
        ))}
      </Svg>
    ),
  );
  component.displayName = name;
  return component;
}

